import { AuthType, EmbedConfig } from '@thoughtspot/visual-embed-sdk';

/** ThoughtSpot worksheet / model GUID for Search, Stella (AI), and Explore embeds */
export const THOUGHTSPOT_MODEL_ID = 'cd252e5c-b552-49a8-821d-3eadaa049cca';

/** Liveboard GUID for LiveboardEmbed (saved dashboard) */
export const THOUGHTSPOT_LIVEBOARD_ID = 'cd408f8e-6f29-4a14-af5f-ddaf57ee04d2';

/** ThoughtSpot Cloud cluster origin (no trailing slash) */
export const thoughtSpotHost = 'https://se-thoughtspot-cloud.thoughtspot.cloud';

/** Maison dark background — matches the host app chrome */
export const EMBED_APP_BACKGROUND = '#1C1C1E';

/** Top header height in App layout (see TopHeader) */
export const TOP_HEADER_PX = 56;

/** Usable height for a full-page embed below the top bar */
export const VIEWPORT_LESS_TOP_HEADER = `calc(100vh - ${TOP_HEADER_PX}px)`;

const publicBase = process.env.PUBLIC_URL ?? '';

/** URL to SVG sprite with `<symbol id="rd-icon-spotter">` (ThoughtSpot iconSpriteUrl — not a raw logo) */
export const DATABOT_ICON_URL = `${publicBase}/databot-robot.svg`;

// ─── Brand palette ───────────────────────────────────────────────────────────
const BRAND_PINK        = '#FF2D55';
const BRAND_PINK_DARK   = '#C9184A';
const BRAND_PINK_GLOW   = 'rgba(255,45,85,0.22)';

// Dark surface scale (matches host app)
const DARK             = '#1C1C1E';   // base background
const DARK_2           = '#2C2C2E';   // card / tile surface
const DARK_3           = '#3A3A3C';   // elevated surface — inputs, hover bg

const WHITE            = '#ffffff';
const WHITE_70         = 'rgba(255,255,255,0.70)';
const WHITE_45         = 'rgba(255,255,255,0.45)';

const APPLE_FONT       = "-apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', sans-serif";

/**
 * Full CSS variable map — all surfaces set to Maison dark theme.
 * Variable names sourced from the ThoughtSpot CSS Variables Reference:
 * https://developers.thoughtspot.com/docs/css-variables-reference
 */
const embedStyleVariables: Record<string, string> = {
  // ── Application-wide ──────────────────────────────────────────────────────
  '--ts-var-root-background':                          DARK,
  '--ts-var-root-color':                               WHITE,
  '--ts-var-root-secondary-color':                     WHITE_70,
  '--ts-var-root-font-family':                         APPLE_FONT,
  '--ts-var-application-color':                        BRAND_PINK,

  // ── Liveboard layout ──────────────────────────────────────────────────────
  '--ts-var-liveboard-layout-background':              DARK,
  '--ts-var-liveboard-header-background':              DARK_2,
  '--ts-var-liveboard-header-font-color':              WHITE,
  '--ts-var-liveboard-notetitle-heading-font-color':   WHITE,
  '--ts-var-liveboard-notetitle-body-font-color':      WHITE_70,
  '--ts-var-liveboard-tile-background':                DARK_2,
  '--ts-var-liveboard-tile-border-radius':             '12px',
  '--ts-var-liveboard-tile-border-color':              DARK_3,
  '--ts-var-liveboard-group-background':               DARK,
  '--ts-var-liveboard-group-title-font-color':         WHITE,
  '--ts-var-liveboard-group-border-color':             DARK_3,
  '--ts-var-liveboard-group-description-font-color':   WHITE_45,
  '--ts-var-liveboard-group-tile-title-font-color':    WHITE,
  '--ts-var-parameter-chip-text-color':                BRAND_PINK,

  // ── Visualization tiles ───────────────────────────────────────────────────
  '--ts-var-viz-background':                           DARK_2,
  '--ts-var-viz-border-radius':                        '12px',
  '--ts-var-viz-box-shadow':                           '0 2px 16px rgba(0,0,0,0.4)',
  '--ts-var-viz-title-color':                          WHITE,
  '--ts-var-viz-title-font-family':                    APPLE_FONT,
  '--ts-var-viz-description-color':                    WHITE_70,
  '--ts-var-viz-description-font-family':              APPLE_FONT,
  '--ts-var-viz-legend-hover-background':              BRAND_PINK_GLOW,

  // ── Chart axis text ───────────────────────────────────────────────────────
  '--ts-var-axis-title-color':                         WHITE_70,
  '--ts-var-axis-title-font-family':                   APPLE_FONT,
  '--ts-var-axis-data-label-color':                    WHITE_45,
  '--ts-var-axis-data-label-font-family':              APPLE_FONT,

  // ── Buttons — primary (pink) ──────────────────────────────────────────────
  '--ts-var-button--primary-background':               BRAND_PINK,
  '--ts-var-button--primary-color':                    WHITE,
  '--ts-var-button--primary--hover-background':        BRAND_PINK_DARK,
  '--ts-var-button--primary--active-background':       BRAND_PINK_DARK,
  '--ts-var-button--primary--font-family':             APPLE_FONT,

  // ── Buttons — secondary ───────────────────────────────────────────────────
  '--ts-var-button--secondary-background':             DARK_3,
  '--ts-var-button--secondary-color':                  WHITE_70,
  '--ts-var-button--secondary--hover-background':      BRAND_PINK_GLOW,
  '--ts-var-button--secondary--active-background':     BRAND_PINK_GLOW,
  '--ts-var-button--secondary--font-family':           APPLE_FONT,

  // ── Buttons — tertiary ────────────────────────────────────────────────────
  '--ts-var-button--tertiary-background':              'transparent',
  '--ts-var-button--tertiary-color':                   WHITE_45,
  '--ts-var-button--tertiary--hover-background':       DARK_3,
  '--ts-var-button--tertiary--active-background':      DARK_3,

  // ── Button border-radius ──────────────────────────────────────────────────
  '--ts-var-button-border-radius':                     '24px',
  '--ts-var-button--icon-border-radius':               '50%',

  // ── Filter chips ──────────────────────────────────────────────────────────
  '--ts-var-chip-background':                          BRAND_PINK_GLOW,
  '--ts-var-chip-color':                               BRAND_PINK,
  '--ts-var-chip-border-radius':                       '20px',
  '--ts-var-chip--active-background':                  BRAND_PINK,
  '--ts-var-chip--active-color':                       WHITE,
  '--ts-var-chip--hover-background':                   BRAND_PINK_DARK,
  '--ts-var-chip--hover-color':                        WHITE,
  '--ts-var-chip-title-font-family':                   APPLE_FONT,

  // ── Menu panels ───────────────────────────────────────────────────────────
  '--ts-var-menu-color':                               WHITE,
  '--ts-var-menu-background':                          DARK_2,
  '--ts-var-menu-font-family':                         APPLE_FONT,
  '--ts-var-menu--hover-background':                   BRAND_PINK_GLOW,
  '--ts-var-menu-selected-text-color':                 BRAND_PINK,
  '--ts-var-menu-separator-background':                DARK_3,

  // ── Dialogs ───────────────────────────────────────────────────────────────
  '--ts-var-dialog-body-background':                   DARK_2,
  '--ts-var-dialog-body-color':                        WHITE,
  '--ts-var-dialog-header-background':                 DARK,
  '--ts-var-dialog-header-color':                      WHITE,
  '--ts-var-dialog-footer-background':                 DARK_2,

  // ── Navigation / search bars ──────────────────────────────────────────────
  '--ts-var-nav-background':                           DARK,
  '--ts-var-search-bar-background':                    DARK_2,
  '--ts-var-search-auto-complete-background':          DARK_2,
  '--ts-var-search-navigation-button-background':      DARK_3,
  '--ts-var-search-bar-navigation-help-text-background': DARK_3,

  // ── Stella (Spotter) AI interface ─────────────────────────────────────────
  '--ts-var-spotter-input-background':                 DARK_2,
  '--ts-var-spotter-prompt-background':                DARK_3,

  // ── Answer / data panel ───────────────────────────────────────────────────
  '--ts-var-answer-data-panel-background-color':       DARK_2,
};

/**
 * SDK init — NoAuth assumes the user is already logged in to ThoughtSpot in the browser.
 */
export function buildThoughtSpotEmbedConfig(): EmbedConfig {
  return {
    thoughtSpotHost,
    authType: AuthType.None,
    suppressSearchEmbedBetaWarning: true,
    customizations: {
      iconSpriteUrl: DATABOT_ICON_URL,
      style: {
        customCSS: {
          variables: embedStyleVariables,
          rules_UNSTABLE: {
            // ── Filter bar padding ───────────────────────────────────────────
            '[class*="filterRow"]':        { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
            '[class*="filter-row"]':       { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
            '[class*="compactHeader"]':    { 'padding-top': '4px !important', 'padding-bottom': '4px !important', 'min-height': 'unset !important' },
            '[class*="compact-header"]':   { 'padding-top': '4px !important', 'padding-bottom': '4px !important', 'min-height': 'unset !important' },
            '[class*="liveboardFilter"]':  { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
            '[class*="FilterBar"]':        { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },

            // ── Table cells inside viz tiles ─────────────────────────────────
            '[class*="tableCell"]':        { 'color': 'rgba(255,255,255,0.85) !important' },
            '[class*="table-cell"]':       { 'color': 'rgba(255,255,255,0.85) !important' },
